-- Create table with fillfactor=70 to reserve space for HOT chains
CREATE TABLE sessions (
  session_id  uuid PRIMARY KEY,
  user_id     bigint NOT NULL,           -- indexed, never updated
  last_seen   timestamptz NOT NULL,      -- updated frequently
  data        jsonb
) WITH (fillfactor = 70);

CREATE INDEX idx_sessions_user ON sessions (user_id);

-- This UPDATE qualifies as HOT: only last_seen changes, not user_id
UPDATE sessions SET last_seen = now() WHERE session_id = $1;

-- Verify HOT updates via pg_stat_user_tables
SELECT n_tup_upd, n_tup_hot_upd,
       round(100.0 * n_tup_hot_upd / NULLIF(n_tup_upd,0), 1) AS hot_pct
FROM pg_stat_user_tables
WHERE relname = 'sessions';

-- PostgreSQL: create a hash index for equality-only lookups
CREATE INDEX idx_sessions_token
  ON sessions USING hash (token);

-- Hash indexes only help equality predicates:
-- Uses the index:
SELECT * FROM sessions WHERE token = 'abc123';
-- Cannot use the hash index:
SELECT * FROM sessions WHERE created_at > NOW() - INTERVAL '1 hour';

-- Create a secondary index
CREATE INDEX idx_orders_user_id ON orders (user_id);

-- InnoDB: secondary index lookup path
-- EXPLAIN shows 'Using index' if covering, else 'Using where'
EXPLAIN SELECT * FROM orders WHERE user_id = 42;
-- Non-covering: secondary B-tree traversal → primary key → primary B-tree

-- InnoDB: primary key = clustered index (rows live in leaf pages)
CREATE TABLE orders (
    order_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id  BIGINT UNSIGNED NOT NULL,
    total    DECIMAL(10,2),
    PRIMARY KEY (order_id)          -- this IS the table storage
) ENGINE=InnoDB;

-- Range scan is sequential I/O on the clustered index:
SELECT * FROM orders WHERE order_id BETWEEN 1000 AND 2000;

-- PostgreSQL: inspect current WAL write position
SELECT pg_current_wal_lsn();
-- Returns: 0/3A1B8C0

-- How much WAL has been generated since a point
SELECT pg_wal_lsn_diff(
    pg_current_wal_lsn(),
    '0/3A1B8C0'
) AS wal_bytes_generated;

-- Manual vacuum with verbose output
VACUUM (VERBOSE, ANALYZE) orders;

-- Check dead tuple counts
SELECT relname, n_live_tup, n_dead_tup,
       last_vacuum, last_autovacuum
FROM pg_stat_user_tables
WHERE relname = 'orders';

-- Force immediate autovacuum (resets dead-tuple counter)
SELECT pg_stat_reset_single_table_counters('orders'::regclass);

-- Refresh statistics for one table
ANALYZE orders;

-- Inspect column statistics
SELECT attname, n_distinct, correlation
FROM pg_stats
WHERE tablename = 'orders'
ORDER BY attname;

-- Increase statistics target for a skewed column
ALTER TABLE orders
  ALTER COLUMN status SET STATISTICS 500;
ANALYZE orders;
